buy_code:
# ================================
#  min 09:00~15:00 세션 회전/수급 지속
# ================================
매수 = True

if not (관심종목 == 1):
    매수 = False
elif not ({entry_start} <= 시분초 <= {entry_end}):
    매수 = False
elif not (데이터길이 >= {min_len}):
    매수 = False
elif not ({price_min} < 현재가 <= {price_max}):
    매수 = False
elif not ({rate_min} <= 등락율 <= {rate_max}):
    매수 = False
elif not (시가총액 <= {cap_max}):
    매수 = False
elif not (당일거래대금 >= {day_money_min}):
    매수 = False
elif not (전일동시간비 >= {prev_ratio_min}):
    매수 = False
elif not (회전율 >= {turnover_min}):
    매수 = False
elif not (분당거래대금 >= 분당거래대금평균({money_avg_window}, 1) * {money_lift_ratio}):
    매수 = False
elif not (분당매수수량 >= 분당매도수량 * {minute_buy_ratio}):
    매수 = False
elif not (누적분당매수수량({acc_window}) >= 누적분당매도수량({acc_window}) * {acc_buy_ratio}):
    매수 = False
elif not (체결강도 >= 체결강도평균({strength_avg_window}, 1) * {strength_lift_ratio}):
    매수 = False
elif not (현재가 >= 이동평균({ma_window}, 1) * {ma_reclaim}):
    매수 = False
elif not (등락율각도({angle_window}) >= {angle_floor}):
    매수 = False

if 매수:
    self.Buy()

sell_code:
# ================================
#  min 09:00~15:00 세션 청산
# ================================
매도 = False

if 등락율 > 29.5:
    매도 = True
elif 수익률 >= {take_rate}:
    매도 = True
elif 수익률 <= {stop_rate}:
    매도 = True
elif 최고수익률 >= {trail_start} and 수익률 <= 최고수익률 - {trail_gap}:
    매도 = True
elif 보유시간 >= {max_hold_min}:
    매도 = True
elif 시분초 >= {force_exit_time}:
    매도 = True

if 매도:
    self.Sell()
